import { createAudioPlayer, type AudioPlayer } from 'expo-audio';
import type { ConceptId } from './concepts';

// Generated by scripts/make-sfx.mjs.
const SOURCES = {
  'futbol-tap': require('../assets/sfx/futbol-tap.wav'),
  'cadilar-tap': require('../assets/sfx/cadilar-tap.wav'),
  'unluler-tap': require('../assets/sfx/unluler-tap.wav'),
  'arabalar-tap': require('../assets/sfx/arabalar-tap.wav'),
  'hayvanlar-tap': require('../assets/sfx/hayvanlar-tap.wav'),
  'yemekler-tap': require('../assets/sfx/yemekler-tap.wav'),
  'diger-tap': require('../assets/sfx/diger-tap.wav'),
  whoosh: require('../assets/sfx/whoosh.wav'),
} as const;

type SfxName = keyof typeof SOURCES;

const players = new Map<SfxName, AudioPlayer>();
let enabled = true;

/** Plays a sound; returns false when app sounds are off. */
function play(name: SfxName, volume = 0.7): boolean {
  if (!enabled) return false;
  try {
    let p = players.get(name);
    if (!p) {
      p = createAudioPlayer(SOURCES[name]);
      players.set(name, p);
    }
    p.volume = volume;
    p.seekTo(0);
    p.play();
    return true;
  } catch {
    return false;
  }
}

export const sfx = {
  setEnabled: (on: boolean) => {
    enabled = on;
    if (!on) players.forEach(p => p.pause());
  },
  tap: (id: ConceptId, volume?: number) => play(`${id}-tap`, volume),
  whoosh: () => play('whoosh', 0.6),
};
